mapper.insert:
INSERT INTO reply (
    message_id, user_id, content, create_time, update_time, status, content_status
) VALUES (
    #{messageId}, #{userId}, #{content}, NOW(), NOW(), #{status}, 'PENDING'
)

mapper.update:
UPDATE reply
SET status = 0,
    content_status = 'REMOVED',
    reviewed_by_user_id = CASE WHEN EXISTS (
        SELECT 1 FROM user actor
        WHERE actor.id = #{actorUserId}
          AND actor.level = 0
    ) THEN #{actorUserId} ELSE reviewed_by_user_id END,
    reviewed_at = CASE WHEN EXISTS (
        SELECT 1 FROM user actor
        WHERE actor.id = #{actorUserId}
          AND actor.level = 0
    ) THEN NOW() ELSE reviewed_at END,
    review_reason_code = CASE WHEN EXISTS (
        SELECT 1 FROM user actor
        WHERE actor.id = #{actorUserId}
          AND actor.level = 0
    ) THEN #{reasonCode} ELSE review_reason_code END,
    removed_by_user_id = #{actorUserId},
    removed_at = NOW(),
    removal_reason_code = #{reasonCode},
    update_time = NOW()
WHERE id = #{id}
  AND content_status <> 'REMOVED'
  AND (
      user_id = #{actorUserId}
      OR EXISTS (
          SELECT 1 FROM user actor
          WHERE actor.id = #{actorUserId}
            AND actor.level = 0
      )
  )

mapper.select:
SELECT COUNT(1)
FROM reply
WHERE user_id = #{userId}
  AND message_id = #{messageId}
  AND create_time >= #{since}
  AND LOWER(TRIM(content)) = LOWER(TRIM(#{content}))
